-- 2026-11-16: align Cane's syllabus with the real course files; Storms 101 -> 4 weeks @ $49; weekly documents
UPDATE classes SET lesson_count=4, price_cents=4900,
  subtitle='Thunderstorms, tornadoes, hurricanes & blizzards — and how we stay safe'
  WHERE id='cw-storms-101';
DELETE FROM lessons WHERE class_id='cw-storms-101' AND position>4;
UPDATE lessons l SET title=v.t, duration_min=v.d FROM (VALUES
('cw-storms-101',1,'Thunderstorms: When Thunder Roars, Go Indoors',20),
('cw-storms-101',2,'Tornadoes: The Spinning Storm',20),
('cw-storms-101',3,'Hurricanes: Giant Storms From the Ocean',20),
('cw-storms-101',4,'Blizzards: Snow, Wind & Staying Warm — Graduation!',25),
('cw-weather-academy',1,'What Is Weather?',25),
('cw-weather-academy',2,'The Sun: Our Weather Engine',25),
('cw-weather-academy',3,'The Water Cycle',25),
('cw-weather-academy',4,'Clouds',25),
('cw-weather-academy',5,'Rain, Snow & Precipitation',25),
('cw-weather-academy',6,'Wind & Air',25),
('cw-weather-academy',7,'The Four Seasons',25),
('cw-weather-academy',8,'Be a Meteorologist — Graduation!',30)
) AS v(c,p,t,d) WHERE l.class_id=v.c AND l.position=v.p;

CREATE TABLE IF NOT EXISTS lesson_documents (
  id         BIGSERIAL PRIMARY KEY,
  lesson_id  BIGINT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('parent-guide','reading','homework','activity-sheet','student-handout','quiz','certificate')),
  blob_key   TEXT NOT NULL,          -- e.g. cw-storms-101/w1/reading.pdf
  file_name  TEXT NOT NULL,          -- download name shown to families
  bytes      INT,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (lesson_id, kind)
);

